import { cash, runway } from '../format.js';
import PlanContext from './PlanContext.jsx';

function Chart({ plan }) {
  const n = plan.duration_assessment.months;
  const a = plan.after_shock;
  // Stacked scenarios with different durations come with the month-by-month path; otherwise it's a straight line.
  const vals = plan.duration_assessment.buffer_path
    ?? Array.from({ length: n + 1 }, (_, i) => a.buffer + i * (a.income - a.spending));
  const hi = Math.max(1, ...vals);
  const lo = Math.min(0, ...vals);
  const y = v => 20 + ((hi - v) / (hi - lo)) * 240;
  const x = i => 20 + (i / n) * 360;
  return (
    <div className="chart">
      <h3>Buffer through the scenario</h3>
      <small>Approximation from rounded API values. Negative values represent unfunded spending, not approved borrowing.</small>
      <svg viewBox="0 0 400 300" role="img" aria-label={`Projected buffer over ${n} months`}>
        <line x1="20" y1={y(0)} x2="380" y2={y(0)} stroke="#cbd6ca" strokeDasharray="4" />
        <polyline points={vals.map((v, i) => `${x(i)},${y(v)}`).join(' ')} fill="none" stroke="#1c594b" strokeWidth="3" />
        <circle cx="380" cy={y(vals[n])} r="4" fill="#f0854e" />
        <text x="20" y="292" fontSize="12" fill="#65746d">Now</text>
        <text x="380" y="292" fontSize="12" fill="#65746d" textAnchor="end">Month {n}</text>
      </svg>
    </div>
  );
}

export function Explanation({ state }) {
  let body;
  if (!state || state.loading) body = <p>Preparing the explanation…</p>;
  else if (state.error) body = `Calculations are available. Explanation unavailable: ${state.error}`;
  else {
    const t = state.data;
    body = (
      <>
        <h3>What this means</h3><p>{t.summary}</p>
        <h3>Your goal</h3><p>{t.goal_plan_text}</p>
        <h3>Contingency plan</h3><p>{t.backup_plan_text}</p>
        {t.caveat && <p className="warning">{t.caveat}</p>}
        <small>Explanation source: {t.source}</small>
      </>
    );
  }
  return <div className="explanation">{body}</div>;
}

const Mini = ({ label, value }) => <div className="mini"><small>{label}</small><strong>{value}</strong></div>;

function PlanResults({ c, show }) {
  const p = c.plan;
  const b = c.baseline;
  const a = p.after_shock;
  const d = p.duration_assessment;
  const rows = [
    ['Monthly inflows', cash(p.baseline.income), cash(a.income)],
    ['Monthly spending', cash(p.baseline.spending), cash(a.spending)],
    ['Buffer after immediate costs', cash(p.baseline.buffer), cash(a.buffer)],
    ['Monthly shortfall', cash(Math.max(b.spending - b.income, 0)), cash(a.monthly_gap)],
    ['Runway', runway(p.baseline), runway(a)],
    ['Immediate expense', 'Not applicable', cash(a.one_off_costs || 0)],
  ];
  return (
    <>
      <table className="comparison">
        <thead><tr><th>Account {c.account}</th><th>Before</th><th>After</th></tr></thead>
        <tbody>{rows.map(r => <tr key={r[0]}><td>{r[0]}</td><td>{r[1]}</td><td>{r[2]}</td></tr>)}</tbody>
      </table>
      {d && (
        <div className={'outcome' + (d.covers_duration ? '' : ' danger')}>
          <h3>{d.covers_duration ? 'Covered' : 'Funding gap'} over {d.months} months</h3>
          <p>{d.assumption}</p>
          <div className="mini-grid">
            <Mini label="Required starting buffer" value={cash(d.required_starting_buffer)} />
            <Mini label="Additional buffer needed" value={cash(d.additional_buffer_needed)} />
          </div>
        </div>
      )}
      {/* With a chart: chart ~60% wide, the four cards stacked on its right. Without: the usual 2x2 grid. */}
      <div className={d ? 'impact-row' : undefined}>
        {d && <Chart plan={p} />}
        <div className="mini-grid">
          <Mini label="Required monthly spending reduction" value={cash(p.backup_plan.monthly_cut_needed)} />
          <Mini label="Immediate funding needed" value={cash(p.backup_plan.upfront_funding_needed)} />
          <Mini label="Emergency-fund target" value={cash(p.goal_plan.target_amount)} />
          <Mini label="Time to goal at baseline surplus" value={p.goal_plan.months_to_goal === null ? 'Not reachable' : p.goal_plan.months_to_goal + ' months'} />
        </div>
      </div>
      <Explanation state={c.explanation} />
      <PlanContext plan={p} />
      <div className="to-plan">
        <button type="button" onClick={() => show('plan')}>Make a plan for this scenario ↗</button>
      </div>
      <details className="data">
        <summary>Inspect all calculated values and account data</summary>
        <pre>{JSON.stringify({ account: b, plan: p }, null, 2)}</pre>
      </details>
      <p className="fine-print">Amounts are displayed as whole dollars. Estimates are scenario inputs, not observed category budgets.</p>
    </>
  );
}

export default function ResultsPanel({ c, show }) {
  return (
    <section className={'results-panel' + (c.plan ? ' revealed' : '')}>
      <div className="panel-heading">
        <div>
          <h2>See the impact</h2>
          <p id="result-label">{c.plan ? 'Baseline versus your applied scenario.' : 'Your baseline, before a shock.'}</p>
        </div>
      </div>
      <div id="results">
        {c.plan ? <PlanResults c={c} show={show} /> : (
          <>
            <div className="empty">
              <div className="empty-icon">↗</div>
              <h3>One change can tell a bigger story.</h3>
              <p>Describe a scenario to compare your starting point<br />with what happens next.</p>
            </div>
            <details className="data">
              <summary>Explore the full account baseline</summary>
              <pre>{JSON.stringify(c.baseline, null, 2)}</pre>
            </details>
          </>
        )}
      </div>
    </section>
  );
}

import { baselineRunway, cash, runway } from '../format.js';
import ChatPanel from './ChatPanel.jsx';
import ResultsPanel, { Explanation } from './ResultsPanel.jsx';
import ActionPlan from './ActionPlan.jsx';
import AccountInsights from './AccountInsights.jsx';
import PlanContext from './PlanContext.jsx';

// Plan tab: the goal plan always; with an applied scenario, a one-line scenario card on top plus the backup plan.
function PlanView({ c, plan, show }) {
  return (
    <div className="plan-view">
      <ActionPlan key={c.planVersion} plan={plan} scenario={c.plan} onEditScenario={() => show('stress')}
        planning={c.planning} busy={c.busy} error={c.planningError} onSubmit={c.recalculatePlan} />
      <PlanContext plan={plan} />
      {c.plan ? <Explanation state={c.explanation} /> : (
        <div className="add-stress">
          <p>Want to see how a job loss, rent hike or surprise bill would change this? Add a stress test to get a backup plan.</p>
          <button type="button" onClick={() => show('stress')}>Add a stress test ↗</button>
        </div>
      )}
    </div>
  );
}

function Metrics({ baseline: b, plan }) {
  if (!b) return <div id="metrics" className="metrics" />;
  const base = plan?.baseline || baselineRunway(b);
  const cards = [
    ['Monthly inflows', cash(b.income), 'Median recorded money in'],
    ['Monthly spending', cash(b.spending), 'Median recorded money out'],
    ['Household bills', cash(b.household_bills), 'Recorded category, not rent alone'],
    ['Fixed costs', cash(b.fixed_costs), 'Median of monthly bills + insurance + loans'],
    ['Savings buffer', cash(b.buffer), 'Mean balance over last six months'],
    ['Baseline runway', runway(base), base.runway_capped ? 'Capped at 120 months' : 'Under typical conditions'],
  ];
  return (
    <div id="metrics" className="metrics">
      {cards.map(([label, value, note], i) => (
        <div key={label} className={'metric' + (i === 4 ? ' highlight' : '')}>
          <label>{label}</label><strong>{value}</strong><small>{note}</small>
        </div>
      ))}
    </div>
  );
}

export default function Dashboard({ hidden, view, show, isAdmin, c, accountInput, setAccountInput }) {
  const b = c.baseline;
  const activePlan = c.plan?.action_plan ? c.plan : c.basePlan?.action_plan ? c.basePlan : null;
  const planEmpty = view === 'plan' && !activePlan;
  const meta = b ? `${b.months_of_history} months on record · Loan payment ${cash(b.loan_payment)} per month` : 'Loading account...';

  function submitAccount(e) {
    e.preventDefault();
    if (isAdmin && !c.busy) c.loadAccount(Number(accountInput));
  }

  return (
    <main id="dashboard" hidden={hidden}>
      <section className="intro">
        <div>
          <p className="eyebrow">{isAdmin ? 'YOUR FINANCIAL MONITORING LAB' : 'YOUR FINANCIAL WHAT-IF LAB'}</p>
          <h1>Your money,<br />a little clearer.</h1>
          <p className="sub">Explore an account. Apply a shock. Find the buffer you need.</p>
        </div>
        {/* Same card in both modes; customers see their account ID read-only and get no Load button. */}
        <form id="account-form" className="account-box" onSubmit={submitAccount}>
          <label htmlFor="account-id">ACCOUNT</label>
          <div className="account-input">
            <input id="account-id" type="number" min="1" list={isAdmin ? 'accounts' : undefined} required aria-label="Account ID"
              value={isAdmin ? accountInput : c.account} onChange={e => setAccountInput(e.target.value)}
              readOnly={!isAdmin} disabled={c.busy} />
            {isAdmin && <datalist id="accounts">{c.accountIds.map(id => <option key={id} value={id} />)}</datalist>}
            {isAdmin && <button type="submit" disabled={c.busy}>Load account ↗</button>}
          </div>
          <small id="account-meta">{meta}</small>
        </form>
      </section>

      <div id="page-error" className="notice error" role="alert" hidden={!c.pageError}>{c.pageError}</div>

      <section id="customer-snapshot" aria-labelledby="snapshot-title">
        <div className="section-title">
          <div className="title-with-help">
            <h2 id="snapshot-title">Your starting point</h2>
            <button type="button" className="help-pill" onClick={() => show('data')} aria-label="How did we get this data?">
              <span className="help-icon" aria-hidden="true">?</span>
              <span className="help-text" aria-hidden="true">How did we get this data?</span>
            </button>
          </div>
          <span>Typical monthly values · CAD</span>
        </div>
        <Metrics baseline={b} plan={c.plan} />
        <AccountInsights baseline={b} />
      </section>

      {/* Kept mounted on the Plan tab so the chat survives switching back. */}
      <div className="workspace" hidden={view === 'plan'}>
        <ChatPanel c={c} />
        <ResultsPanel c={c} show={show} />
      </div>

      {view === 'plan' && activePlan && <PlanView c={c} plan={activePlan} show={show} />}

      <div id="plan-empty" className="empty" hidden={!planEmpty}>
        <h2>Build a plan from your own numbers.</h2>
        <p>{b ? 'Calculating your goal plan…' : 'Load an account to calculate your goal plan.'} Apply a scenario in Stress Test to add a backup plan.</p>
        <button type="button" onClick={() => show('stress')}>Create a stress test ↗</button>
      </div>

      <footer>
        <span>CUSHION / SHERIDAN DATATHON 2026</span>
        <span>Scenario analysis using anonymized account data. Recorded inflows are not verified salary.</span>
      </footer>
    </main>
  );
}

